def backfill_usage_days(apps, schema_editor):
    """Meter the history the workspace already has: executions per UTC day
    from the runs still stored, and each such day's projects as those that
    existed by then and still exist. Runs and projects deleted before
    metering began are gone, so history can only undercount."""
    from datetime import timezone

    StandardExecution = apps.get_model("app", "StandardExecution")
    Project = apps.get_model("app", "Project")
    WorkspaceUsageDay = apps.get_model("app", "WorkspaceUsageDay")

    per_day = (
        StandardExecution.objects.annotate(day=TruncDate("created_at", tzinfo=timezone.utc))
        .values("project__tenant_id", "day")
        .annotate(runs=Count("id"))
    )
    created = {}
    for tenant_id, at in Project.objects.values_list("tenant_id", "created_at"):
        created.setdefault(tenant_id, []).append(at.astimezone(timezone.utc).date())
    WorkspaceUsageDay.objects.bulk_create(
        [
            WorkspaceUsageDay(
                tenant_id=row["project__tenant_id"],
                day=row["day"],
                executions=row["runs"],
                peak_projects=sum(d <= row["day"] for d in created.get(row["project__tenant_id"], [])),
            )
            for row in per_day
        ],
        ignore_conflicts=True,
    )



